return items.map(item => {
  const raw =
    item.json.text ||
    item.json.response ||
    item.json.output ||
    item.json.completion ||
    '';

  let parsed = {};

  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    parsed = {
      summary: raw,
      why_it_matters: '',
      relevance_score: 0,
      parse_error: true
    };
  }

  return {
    json: {
      ...item.json,
      ...parsed
    }
  };
});

const inputItems = $input.all();

const results = inputItems.filter((item) => {
  const data = item.json || {};

  // Read relevance score from common possible locations
  const rawScore =
    data.relevance_score ??
    data.relevanceScore ??
    data.score ??
    data.output?.relevance_score ??
    data.output?.relevanceScore ??
    data.output?.score ??
    0;

  const score = Number(rawScore);

  // Handle parse_error as boolean or string
  const rawParseError =
    data.parse_error ??
    data.parseError ??
    data.output?.parse_error ??
    data.output?.parseError ??
    false;

  const hasParseError =
    rawParseError === true ||
    String(rawParseError).trim().toLowerCase() === "true";

  return !hasParseError && !Number.isNaN(score) && score >= 7;
});

return results;

return [{
  json: {
    articles: items.map(item => ({
      title: item.json.title,
      summary: item.json.summary,
      why_it_matters: item.json.why_it_matters,
      relevance_score: item.json.relevance_score,
      link: item.json.link
    }))
  }
}];

const raw = String($input.first().json.text || '').trim();

if (!raw) {
  return [{
    json: {
      error: 'empty_response',
      reason: 'The text field is empty.'
    }
  }];
}

let text = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// Prefer content after a completed thinking block
const thinkEnd = text.toLowerCase().lastIndexOf('</think>');

if (thinkEnd !== -1) {
  text = text.slice(thinkEnd + '</think>'.length).trim();
}

// Find all possible JSON objects
const candidates = [];
let depth = 0;
let start = -1;
let inString = false;
let escaped = false;

for (let i = 0; i < text.length; i++) {
  const char = text[i];

  if (escaped) {
    escaped = false;
    continue;
  }

  if (char === '\\' && inString) {
    escaped = true;
    continue;
  }

  if (char === '"') {
    inString = !inString;
    continue;
  }

  if (inString) {
    continue;
  }

  if (char === '{') {
    if (depth === 0) {
      start = i;
    }

    depth++;
  } else if (char === '}') {
    depth--;

    if (depth === 0 && start !== -1) {
      candidates.push(text.slice(start, i + 1));
      start = -1;
    }
  }
}

// Try candidates from last to first because final output is usually last
let parsed = null;
let selectedCandidate = null;
let lastError = null;

for (let i = candidates.length - 1; i >= 0; i--) {
  const candidate = candidates[i].trim();

  // Skip schema examples containing placeholders
  if (
    candidate.includes('...') ||
    candidate.includes('…')
  ) {
    continue;
  }

  try {
    const value = JSON.parse(candidate);

    if (
      Array.isArray(value?.ideas) ||
      value?.angle ||
      value?.hook
    ) {
      parsed = value;
      selectedCandidate = candidate;
      break;
    }
  } catch (error) {
    lastError = error.message;
  }
}

if (!parsed) {
  return [{
    json: {
      error: 'no_valid_final_json',
      reason:
        'The model produced reasoning or a schema example, but did not complete the final JSON response.',
      parse_error: lastError,
      candidate_count: candidates.length,
      response_appears_truncated:
        raw.includes('<think>') &&
        !raw.includes('</think>'),
      raw
    }
  }];
}

let ideas = [];

if (Array.isArray(parsed.ideas)) {
  ideas = parsed.ideas;
} else if (
  parsed.ideas &&
  typeof parsed.ideas === 'object'
) {
  ideas = [parsed.ideas];
} else if (parsed.angle || parsed.hook) {
  ideas = [parsed];
}

if (!ideas.length) {
  return [{
    json: {
      error: 'no_ideas_found',
      parsed,
      selectedCandidate
    }
  }];
}

return ideas
  .slice(0, 3)
  .map((idea, index) => ({
    json: {
      idea_number: index + 1,
      angle: idea.angle || '',
      hook: idea.hook || '',
      related_service: idea.related_service || '',
      target_audience: idea.target_audience || ''
    }
  }));

return items.map(item => {
