const keywords = [
  'ai','cloud','startup','developer','saas',
  'automation','machine learning','data','security'
];

return items.filter(item => {
  const text = (item.json.title + ' ' + item.json.snippet).toLowerCase();
  return keywords.some(k => text.includes(k));
});

// Process a maximum of 10 articles
return items.slice(0, 10).map(item => {
  const a = item.json;

  const promptPayload = {
    model: "llama-3.3-70b-versatile",
    temperature: 0.3,
    prompt: `
