  { json: { url: 'https://www.theverge.com/rss/index.xml', source: 'The Verge' } },
  { json: { url: 'https://feeds.arstechnica.com/arstechnica/index', source: 'Ars Technica' } }
];

const randomItem = items[Math.floor(Math.random() * items.length)];

return [
  {
    json: randomItem.json
  }
];

const raw =
  items[0].json.text ||
  items[0].json.response ||
  items[0].json.output ||
  '';

// Ensure it's always treated as string content
let mdx = '';

try {
  mdx = typeof raw === 'string' ? raw : JSON.stringify(raw);
} catch (e) {
  mdx = 'Error: Unable to process MDX content';
}

return [
  {
    json: {
      content: mdx
    }
  }
];

const d = items[0]?.json ?? {};

// Support common AI-node response fields
let content =
  d.content ??
  d.text ??
  d.output ??
  d.message?.content ??
  '';

// Ensure the content is a string
if (typeof content !== 'string') {
  content = JSON.stringify(content, null, 2);
}

// Remove accidental Markdown code fences
content = content
  .replace(/^```(?:md|mdx|markdown)?\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

// Extract only the YAML frontmatter block
const frontmatterMatch = content.match(/^---\s*\r?\n([\s\S]*?)\r?\n---/);
const frontmatter = frontmatterMatch?.[1] ?? '';

// Extract a quoted or unquoted frontmatter field
const getField = (key) => {
  const escapedKey = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const match = frontmatter.match(
    new RegExp(
      `^${escapedKey}:\\s*(?:"([^"]*)"|'([^']*)'|([^\\r\\n]+))\\s*$`,
      'mi'
    )
  );

  return (
    match?.[1] ??
    match?.[2] ??
    match?.[3]?.trim() ??
    ''
  );
};

// Extract metadata
const title = getField('title') || 'Untitled';
const description = getField('description');
const category = getField('category') || 'Blog';
const author =
  getField('author') || 'Mayhem Softwares Bangladesh';

// Normalize the date to YYYY-MM-DD
const rawDate = getField('date');
const parsedDate = rawDate ? new Date(rawDate) : new Date();

const date = Number.isNaN(parsedDate.getTime())
  ? new Date().toISOString().slice(0, 10)
  : parsedDate.toISOString().slice(0, 10);

// Generate a safe slug
const slug =
  title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 100) || 'untitled';

// Generate filenames
const baseFileName = `${date}-${slug}`;
const mdxFileName = `${baseFileName}.mdx`;
const manifestFileName = `${baseFileName}.json`;

// Manifest object
const manifest = {
  title,
  description,
  date,
  slug,
  category,
  author,
  file: mdxFileName
};

// Return two n8n items
return [
  {
    json: {
      type: 'mdx',
      fileName: mdxFileName,
      mimeType: 'text/mdx',
      fileContent: content
    }
  },
  {
    json: {
      type: 'manifest',
      fileName: manifestFileName,
      mimeType: 'application/json',
      fileContent: JSON.stringify(manifest, null, 2)
    }
  }
];
